package com.gameaggregator.billingservice.api;import com.gameaggregator.platform.core.common.web.ApiResponse;import com.gameaggregator.billingservice.application.BillingService;import com.gameaggregator.billingservice.domain.*;import jakarta.validation.Valid;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/billing") public class BillingController{final BillingService s;public BillingController(BillingService s){this.s=s;}@PostMapping("/plans")ApiResponse<BillingPlan> plan(@Valid @RequestBody BillingDtos.Plan r){return ApiResponse.success(s.plan(r));}@PostMapping("/usage")ApiResponse<UsageRecord> usage(@Valid @RequestBody BillingDtos.Usage r){return ApiResponse.success(s.usage(r));}@PostMapping("/invoices")ApiResponse<Invoice> invoice(@Valid @RequestBody BillingDtos.InvoiceRequest r){return ApiResponse.success(s.invoice(r));}@PostMapping("/invoices/{id}/items")ApiResponse<InvoiceItem> item(@PathVariable UUID id,@Valid @RequestBody BillingDtos.Item r){return ApiResponse.success(s.item(id,r));}@PostMapping("/invoices/{id}/credit-notes")ApiResponse<CreditNote> credit(@PathVariable UUID id,@Valid @RequestBody BillingDtos.Credit r){return ApiResponse.success(s.credit(id,r));}@PatchMapping("/invoices/{id}/payment")ApiResponse<Invoice> payment(@PathVariable UUID id,@Valid @RequestBody BillingDtos.Payment r){return ApiResponse.success(s.payment(id,r));}@GetMapping("/reports/invoices")ApiResponse<List<Invoice>> report(){return ApiResponse.success(s.report());}}